<template><view class="page"><text class="title">照护任务</text><text class="sub">家庭成员之间的待办与分工</text><view v-for="t in tasks" :key="t.id" class="card task" @tap="open(t)"><view><text class="task-title">{{t.title}}</text><text class="meta">{{t.owner}}负责 · {{t.due}}</text></view><text class="status">{{t.status}}</text></view><button class="add" @tap="add">+ 新增照护任务</button></view></template><script>import {careTasks} from '@/store/mock';export default{data(){return{tasks:[]}},onShow(){const local=uni.getStorageSync('care_tasks_local')||[];this.tasks=[...careTasks,...local]},methods:{add(){uni.navigateTo({url:'/pages/family/task-edit/index'})},open(t){uni.showActionSheet({itemList:['标记已完成','编辑任务','删除任务'],success:r=>{if(r.tapIndex===0){t.status='已完成';uni.showToast({title:'已完成',icon:'success'})}else if(r.tapIndex===1){uni.navigateTo({url:'/pages/family/task-edit/index?title='+encodeURIComponent(t.title)})}else{this.tasks=this.tasks.filter(x=>x.id!==t.id);uni.showToast({title:'已删除',icon:'none'})}}})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#f6f7f3}.title{display:block;font-size:40rpx;font-weight:900;color:#2d4338}.sub{display:block;margin:10rpx 0 26rpx;color:#7b857f;font-size:21rpx}.card{background:#fff;border-radius:26rpx}.task{margin-bottom:16rpx;padding:24rpx;display:flex;justify-content:space-between;align-items:flex-start}.task-title,.meta{display:block}.task-title{font-size:27rpx;font-weight:900}.meta{margin-top:7rpx;font-size:20rpx;color:#7c867f}.status{font-size:19rpx;color:#326a53}.add{margin-top:8rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>